        for (const [px, pz] of [[-0.28, -0.22], [0.28, -0.22], [-0.28, 0.22], [0.28, 0.22]]) silindir(t, 0.018, 0.018, 0.5, "#6E5A44", px, 0, pz, 5);
        const ust = kutu(t, 0.72, 0.05, 0.6, renkler[i % renkler.length], 0, 0.5, 0);
