      yaniklar.forEach((b, i) => { const o = Math.max(b.w, b.d) * (b.savas === 2 ? 0.95 : 0.7); m.setMatrixAt(i, _m.compose(_p.set(b.x, 0.016, b.z), _q.identity(), _o.set(o, 1, o))); });
