        const kat = Math.min(p.boy - 0.1, 0.38 * (1 + (p.sira % 2)) * (hareketAzalt ? 1 : 0.8 + 0.2 * Math.sin(t * 1.3 + p.faz)));
        const yan = (u - 0.5) * 2 * p.w * 0.85;
