    for (const [x, z, gx, gz] of [[-0.6, 0, 0.1, 1.0], [0.6, 0, 0.1, 1.0], [0, -0.45, 1.3, 0.1]]) kutu(kasa, gx, 0.6, gz, celik, x, 0.12, z);
    const kapak = kutu(kasa, 1.3, 0.6, 0.08, celik, 0, 0.12, 0.5);
