    p.g.beginPath(); p.g.arc(80, 74, 30, 0, Math.PI * 2); p.g.fill();
    p.g.beginPath(); p.g.ellipse(80, 158, 54, 42, 0, Math.PI, 0); p.g.fill();
    p.g.fillStyle = "#1F2328"; p.g.fillRect(0, 168, 160, 52);
    p.g.fillStyle = "#FFFFFF"; p.g.font = "bold 20px system-ui, sans-serif"; p.g.textAlign = "center"; p.g.textBaseline = "middle";
