  const fotoParlak = new THREE.InstancedMesh(fotoGeo, new THREE.MeshStandardMaterial({ color: "#FFFFFF", emissive: "#FFF3C8", emissiveIntensity: 0.35, roughness: 0.5 }), MEYDAN_FOTO);
  for (const im of [fotoSonuk, fotoParlak]) { im.count = 0; hatira.add(im); }
  const fotoRenk = ["#7FA6B8", "#C9A26A", "#8DB07A", "#B88A9E", "#9C8CC2", "#C98B6A", "#6FA59C", "#B7A35E", "#8E9DB3"];
  hatira.add(kutu(1.2, 0.08, 0.36, tahta, 0, 0.36, 0.55), kutu(0.07, 0.36, 0.3, tahtaKoyu, -0.5, 0, 0.55), kutu(0.07, 0.36, 0.3, tahtaKoyu, 0.5, 0, 0.55));   // bank
