    if (el.className !== sinif) el.className = sinif;
    const ds = { ad: o.ad ?? "", hedef: `${Math.round(o.hedef[0] * 100)},${Math.round(o.hedef[1] * 100)}`, yuruyor: o.yol ? "1" : "0", eylem: o.eylem ?? "" };
    for (const [k, v] of Object.entries(ds)) if (el.dataset[k] !== v) el.dataset[k] = v;
