    g.strokeStyle = "#7A6F62"; g.lineWidth = 2;
    for (let i = 0; i <= 10; i++) { const a2 = Math.PI + (Math.PI * i) / 10; g.beginPath(); g.moveTo(cx + Math.cos(a2) * (rr - 22), cy + Math.sin(a2) * (rr - 22)); g.lineTo(cx + Math.cos(a2) * (rr - 12), cy + Math.sin(a2) * (rr - 12)); g.stroke(); }
    const a3 = Math.PI + Math.PI * oran;
    g.strokeStyle = "#2B2724"; g.lineWidth = 5; g.lineCap = "round";
    g.beginPath(); g.moveTo(cx, cy); g.lineTo(cx + Math.cos(a3) * (rr - 26), cy + Math.sin(a3) * (rr - 26)); g.stroke();
    g.fillStyle = "#2B2724"; g.beginPath(); g.arc(cx, cy, 10, 0, Math.PI * 2); g.fill();
