    for (let i = 0; i < 4; i++) silindir(g, 0.018, 0.018, 0.02, "#D9B54A", -0.79 + i * 0.07, 0.56, 0.01, 8).rotation.x = Math.PI / 2;
    const govde = golgeli(new THREE.Mesh(new THREE.SphereGeometry(0.22, 20, 14), renkliMat));
    govde.scale.set(1, 1.25, 0.32); govde.position.set(0.25, 0.5, 0);
