    govde2.scale.set(1, 1.1, 0.32); govde2.position.set(0.25, 0.8, 0);
    const sap = golgeli(new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.62, 0.04), M("#6B4E36")));
    sap.position.set(0.25, 1.22, 0);
